preview_html_value+='''<script>const currentViewSelector=document.querySelector('#view-select');const modelOpacityRange=document.querySelector('#opacity-range');const modelOutlineToggle=document.querySelector('#outline-toggle');function updateReferenceComparison(){const selectedViewName=currentViewSelector.value;document.querySelector('#reference-preview').src='reference-'+selectedViewName+'-preview.png';document.querySelector('#overlay-reference').src='reference-'+selectedViewName+'.png';for(const modelImageElement of document.querySelectorAll('[data-model]'))modelImageElement.src='aligned-'+modelImageElement.dataset.model+'-'+selectedViewName+'.png';const overlayModelImage=document.querySelector('#overlay-model');overlayModelImage.src=(modelOutlineToggle.checked?'outline-revised-':'aligned-revised-')+selectedViewName+'.png';overlayModelImage.style.opacity=Number(modelOpacityRange.value)/100;document.querySelector('#opacity-value').textContent=modelOpacityRange.value+'%'}currentViewSelector.onchange=updateReferenceComparison;modelOpacityRange.oninput=updateReferenceComparison;modelOutlineToggle.onchange=updateReferenceComparison;const frameImageElements=[...document.querySelectorAll('[data-prefix]')];const frameRangeElement=document.querySelector('#frame-range');const playbackToggleElement=document.querySelector('#playback-toggle');let currentFrameIndex=0;let animationPlaybackEnabled=true;function updatePreviewFrames(){for(const frameImageElement of frameImageElements)frameImageElement.src=frameImageElement.dataset.prefix+String(currentFrameIndex+1).padStart(2,'0')+'.png';frameRangeElement.value=currentFrameIndex;document.querySelector('#frame-label').textContent=(currentFrameIndex+1)+' / 8'}playbackToggleElement.onclick=()=>{animationPlaybackEnabled=!animationPlaybackEnabled;playbackToggleElement.textContent=animationPlaybackEnabled?'일시정지':'재생'};frameRangeElement.oninput=()=>{animationPlaybackEnabled=false;playbackToggleElement.textContent='재생';currentFrameIndex=Number(frameRangeElement.value);updatePreviewFrames()};setInterval(()=>{if(animationPlaybackEnabled){currentFrameIndex=(currentFrameIndex+1)%8;updatePreviewFrames()}},150);</script></html>'''
